import os

def detect_encoding_and_separator(file_path):
    with open(file_path, 'rb') as f:
        bom = f.read(4)

    if bom.startswith(b'\xff\xfe'):
        encoding = 'utf-16'
    elif bom.startswith(b'\xfe\xff'):
        encoding = 'utf-16'
    elif bom.startswith(b'\xef\xbb\xbf'):
        encoding = 'utf-8-sig'
    else:
        encoding = 'utf-8'

    # Let's open with this encoding and see first 5 lines
    try:
        with open(file_path, 'r', encoding=encoding) as f:
            lines = [f.readline() for _ in range(5)]
    except UnicodeDecodeError:
        # fallback to utf-16 just in case
        encoding = 'utf-16'
        with open(file_path, 'r', encoding=encoding) as f:
            lines = [f.readline() for _ in range(5)]

    # Check separator in line 3 (index 3 is the 4th line, containing headers)
    # The header line in A-D was: timestamp..., inverter_temp...
    # Let's search for ',' or ';' in lines[3] or whichever line has headers
    header_line = ""
    for line in lines:
        if 'timestamp' in line.lower():
            header_line = line
            break

    is_semicolon = ';' in header_line
    sep = ';' if is_semicolon else ','
    decimal = ',' if is_semicolon else '.'

    return encoding, sep, decimal

for fid in [f"FARM_{chr(c)}" for c in range(ord('A'), ord('X')+1)]:
    fpath = f"/app/dataset/production_{fid}.csv"
    if os.path.exists(fpath):
        encoding, sep, decimal = detect_encoding_and_separator(fpath)
        print(f"{fid}: encoding={encoding} sep={repr(sep)} decimal={repr(decimal)}")
    else:
        print(f"{fid}: file does not exist")

